static long CalculateMaxDifferenceSum(List<Integer> A) {
    long total_sum = 0;
    int n = A.size();
    for (int i = 0; i < n - 1; i++) {
        for (int j = i + 1; j < n; j++) {
            int diff = A.get(j) - A.get(i);
            if (diff > 0) {
                total_sum += diff;
            }
        }
    }
    return total_sum;
}
